       , #{r.trType,jdbcType=VARCHAR}, #{r.contPeriodNm,jdbcType=VARCHAR}, #{r.startDate,jdbcType=DATE}, #{r.closeDate,jdbcType=DATE}
       , #{r.manageMinFee,jdbcType=NUMERIC}, #{r.advMinFee,jdbcType=NUMERIC}, #{r.discrMinFee,jdbcType=NUMERIC}, #{r.withFee,jdbcType=NUMERIC}
